-- Look up by the dungeon key BossNav uses everywhere (Norm of the name).
local QUESTS_BY_KEY = {}
for name, list in pairs(QUESTS) do QUESTS_BY_KEY[Norm(name)] = list end

-- The quests of a dungeon config, or an empty list.
local function DungeonQuests(cfg)
    return cfg and QUESTS_BY_KEY[cfg.key] or {}
end

-- shared with the other BossNav files
ns.DungeonQuests = DungeonQuests
